def wire(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")) + "\n"


def chain_events(s):
    events = []
    after = 0
    while True:
        doc = json.loads(s.audit(after=after, limit=1000))
        window = doc["事件"]
        if not window:
            break
        events.extend(window)
        after = doc["下个序号"]
    return events

